import { MALL_PATHS } from './mall-paths.js';
import { MALL_FLOORS, floorForSpot, VIRTUAL_ITEMS, cleanWardrobe, itemById, dressAppearance } from './mall-catalog.js';
import { MALL_SHOPS, shopById, MALL_GEOMETRY, MALL_INFO } from './mall-directory.js';
const $m=s=>document.querySelector(s), me=()=>window.CrowCommunity?.self(), floor=()=>floorForSpot(me()?.spot)||MALL_FLOORS[1], shop=()=>shopById(me()?.shopId);
const R=(x,y,w,h,col)=>{ctx.fillStyle=col;ctx.fillRect(Math.round(x),Math.round(y),w,h);};
const T=(s,x,y,col='#64715c',size=12)=>{ctx.font=`${size}px monospace`;ctx.fillStyle=col;ctx.fillText(s,x,y);};
let selected=null,renderKey='',directoryFloor='all',directoryQuery='';
const colors=['#b7c7b0','#c9bbab','#a7c3c0','#d8c694','#b8b6c8','#b6c19b'];
function hash(s){let n=0;for(const c of s)n=(n*31+c.charCodeAt(0))>>>0;return n;}
const currentShops=()=>MALL_SHOPS.filter(s=>s.floor===floor().id);
function enter(id){const s=shopById(id);if(!s)return;selected=s.id;$m('#mall-shop-dialog').close();window.CrowCommunity.shop(id);}
function itemsFor(s){if(!s)return[];const n=s.name.toLowerCase();return VIRTUAL_ITEMS.filter(i=>n.includes(i.brand.toLowerCase()));}
function closeButton(label='Close shop directory'){return `<button class="icon-btn" data-mall-close aria-label="${label}">×</button>`;}
function bindClose(dialog){dialog.querySelector('[data-mall-close]').onclick=()=>dialog.close();}
function openDirectory(){directoryFloor=floor().id;directoryQuery='';renderDirectory();$m('#mall-shop-dialog').showModal();}
function renderDirectory(){const d=$m('#mall-shop-dialog');d.innerHTML=`<div class="dialog-heading"><div><span class="eyebrow">SURIA KLCC · THE REAL DIRECTORY, IN PIXELS</span><h2>A little window shopping.</h2></div>${closeButton()}</div><div class="mall-search"><label><span class="sr-only">Find a shop</span><input id="mall-search" placeholder="Find Nike, adidas, a café…" value="${safe(directoryQuery)}"></label><select id="mall-filter" aria-label="Filter directory by floor"><option value="all">All six floors</option>${MALL_FLOORS.map(f=>`<option value="${f.id}" ${f.id===directoryFloor?'selected':''}>${f.name}</option>`).join('')}</select></div><p id="mall-results" class="mall-muted"></p><div id="mall-directory-list" class="mall-directory-list"></div><p class="mall-source-note">Official mall directory snapshot · 2 Nov 2026. Shop units follow the official listings; the playable map simplifies the building. <a href="https://www.suriaklcc.com.my/shopping-mall-large/" target="_blank" rel="noopener">Official mall map ↗</a></p>`;bindClose(d);$m('#mall-search').oninput=e=>{directoryQuery=e.target.value;directoryList();};$m('#mall-filter').onchange=e=>{directoryFloor=e.target.value;directoryList();};directoryList();}
function directoryList(){const results=MALL_SHOPS.filter(s=>(directoryFloor==='all'||s.floor===directoryFloor)&&(s.name+' '+s.unit+' '+(s.category||'')).toLowerCase().includes(directoryQuery.trim().toLowerCase()));$m('#mall-results').textContent=results.length+' shops & destinations';$m('#mall-directory-list').innerHTML=results.map(s=>`<button data-shop-id="${safe(s.id)}"><span class="mall-floor-badge">${MALL_FLOORS.find(f=>f.id===s.floor)?.label}</span><span><strong>${safe(s.name)}</strong><small>${safe(s.unit)}${itemsFor(s).length?' · Pixel try-on available':''}</small></span><b>Visit ↗</b></button>`).join('')||'<p class="mall-muted">No shops match. Try another name or floor.</p>';document.querySelectorAll('[data-shop-id]').forEach(b=>b.onclick=()=>enter(b.dataset.shopId));}
function drawItem(c,item,x,y,scale=2){const r=(a,b,w,h,col)=>{c.fillStyle=col;c.fillRect(x+a*scale,y+b*scale,w*scale,h*scale);};if(item.slot==='top'){r(-10,-9,20,23,item.color);r(-15,-7,5,10,item.color);r(10,-7,5,10,item.color);r(-4,-9,8,3,'#e5dfc8');if(item.pattern==='stripes')for(let j=0;j<3;j++){r(-14,-5+j*3,5,1,item.accent);r(10,-5+j*3,5,1,item.accent);}else{r(2,0,7,2,item.accent);r(0,-2,4,2,item.accent);}}else if(item.slot==='bottom'){r(-9,-11,18,8,item.color);r(-9,-3,7,21,item.color);r(2,-3,7,21,item.color);r(-8,-9,1,25,item.accent);r(7,-9,1,25,item.accent);}else if(item.slot==='shoes'){for(const dx of [-12,4]){r(dx,-3,11,12,item.color);r(dx-3,5,14,6,item.color);r(dx-3,10,14,2,item.accent);r(dx+1,0,7,2,item.accent);}}else{r(-10,-6,20,14,item.color);r(-15,7,29,3,item.color);r(-3,-2,6,3,item.accent);}}
function drawItemCanvases(root){root.querySelectorAll('[data-mall-item]').forEach(c=>{const it=itemById(c.dataset.mallItem);if(it)drawItem(c.getContext('2d'),it,40,29,1.6);});}
function itemCard(i,w){const equipped=w.equipped[i.slot]===i.id;return `<button class="mall-item ${equipped?'equipped':''}" data-equip="${i.id}" ${equipped?'disabled':''}><canvas width="80" height="64" data-mall-item="${i.id}" aria-hidden="true"></canvas><span><strong>${safe(i.name)}</strong><small>${i.brand} · ${i.slot}</small></span><b>${equipped?'Wearing ✓':w.owned.includes(i.id)?'Wear ↗':'Collect & wear ↗'}</b></button>`;}
function bindEquip(root){drawItemCanvases(root);root.querySelectorAll('[data-equip]').forEach(b=>b.onclick=async()=>{b.disabled=true;if(!await window.CrowCommunity.equip(b.dataset.equip))b.disabled=false;if($m('#wardrobe-dialog').open)renderWardrobe();});}
function renderWardrobe(){const d=$m('#wardrobe-dialog'),w=cleanWardrobe(me()?.wardrobe);d.innerHTML=`<div class="dialog-heading"><div><span class="eyebrow">YOUR PIXEL WARDROBE</span><h2>A little more you.</h2></div>${closeButton('Close wardrobe')}</div><div class="wardrobe-preview"><canvas id="wardrobe-avatar" width="144" height="144" aria-label="Your character wearing the current outfit"></canvas><div><strong>${safe(me()?.name||'Your character')}</strong><p>Keep your look as you work, wander and visit friends.</p><small>Saved with your remembered guest profile on this browser.</small></div></div><div class="mall-items">${w.owned.map(itemById).map(i=>itemCard(i,w)).join('')||'<p class="mall-muted">Your wardrobe is waiting. Visit Nike or adidas on Level 3 to collect your first free pixel outfit.</p>'}</div><div class="wardrobe-reset">${Object.keys(w.equipped).map(slot=>`<button class="secondary" data-remove="${slot}">Remove ${slot}</button>`).join('')}<button class="primary" id="wardrobe-shop">Visit sports floor ↗</button></div><p class="mall-source-note">Digital dress-up only. Pixel interpretations of brand styles; no real purchase or shop stock is represented.</p>`;bindClose(d);const c=$m('#wardrobe-avatar').getContext('2d');drawSprite(c,window.CrowCommunity.appearance(me()),25,10,6);bindEquip(d);d.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{await window.CrowCommunity.equip(null,b.dataset.remove);renderWardrobe();});$m('#wardrobe-shop').onclick=()=>{d.close();window.CrowCommunity.go('mall-3');};}
function render(){const p=me(),s=shop(),f=floor(),w=cleanWardrobe(p?.wardrobe),key=p?.spot+':'+(s?.id||'')+':'+JSON.stringify(w);if(renderKey===key)return;renderKey=key;const panel=$m('#mall-panel');if(scene!=='mall'&&!p?.spot?.startsWith('mall-')){panel.classList.add('hidden');return;}panel.classList.remove('hidden');panel.innerHTML=`<div class="mall-lift"><div class="mall-identity"><span class="eyebrow">SURIA KLCC / CROW QUARTER</span><strong>${s?safe(s.name):'Six floors. A little adventure.'}</strong><small>${s?safe(s.unit)+' · '+f.name:currentShops().length+' shops & destinations on '+f.name}</small></div><div class="mall-floor-buttons" role="group" aria-label="Mall lift">${MALL_FLOORS.map(a=>`<button data-floor="${a.id}" class="${f.id===a.id?'active':''}" aria-label="Go to ${a.name}" aria-pressed="${f.id===a.id}">${a.label}</button>`).join('')}</div><button class="secondary" id="mall-browse">Browse ${MALL_INFO.tenantCount} brands ↗</button><button class="secondary" id="mall-wardrobe">My wardrobe ◇</button>${s?'<button class="secondary" id="mall-leave-shop">← Mall corridor</button>':''}</div>${s?`<div class="mall-shop-products"><div><span class="eyebrow">${itemsFor(s).length?'THE PIXEL COLLECTION · FREE TO COLLECT':'YOU’RE WINDOW SHOPPING'}</span><p>${itemsFor(s).length?'Choose an item below. Your character wears it around the whole community. Free pixel interpretations; not live store inventory.':'Take a look around '+safe(s.name)+'. Explore the real brand through its official mall listing.'}</p></div><div class="mall-items">${itemsFor(s).map(i=>itemCard(i,w)).join('')}</div></div>`:''}<p class="mall-caption">Official floor and unit listings · snapshot 2 Nov 2026 · simplified pixel recreation${s?' · digital items only':''} ${itemsFor(s).length?'<a href="'+itemsFor(s)[0].source+'" target="_blank" rel="noopener">Brand collection ↗</a> · ':''}<a href="https://www.suriaklcc.com.my/shopping-mall-large/" target="_blank" rel="noopener">Real mall map ↗</a></p>`;panel.querySelectorAll('[data-floor]').forEach(b=>b.onclick=()=>window.CrowCommunity.go('mall-'+b.dataset.floor));$m('#mall-browse').onclick=openDirectory;$m('#mall-wardrobe').onclick=openWardrobe;if(s)$m('#mall-leave-shop').onclick=()=>window.CrowCommunity.shop(null);bindEquip(panel);if(scene==='mall')updateTitle();}
function openWardrobe(){if(!me())return toast('Create your character first.');renderWardrobe();$m('#wardrobe-dialog').showModal();}
function updateTitle(){cv.setAttribute('aria-label',shop()?shop().name+' pixel shop interior on '+floor().name+'. Choose items above to collect and wear.':'Suria KLCC '+floor().name+' pixel floor plan. Click shops to visit or corridors to walk.');$m('#scene-title').textContent=shop()?shop().name+' · '+floor().name:'Suria KLCC · '+floor().name;$m('#world-caption').textContent=shop()?'WINDOW SHOPPING / MAKE IT YOUR OWN':'THE MALL AT CROW HQ · SIX LEVELS';}
function openScene(which){if(which!=='mall')return false;scene='mall';state.scene='mall';save();cv.width=1400;cv.height=1000;ctx.imageSmoothingEnabled=false;$m('#town-tab').classList.remove('active');$m('#indoor-tab').classList.remove('active');$m('#destination-bar').classList.add('hidden');$m('.office-stage').classList.remove('town-scene');$m('#exit-hq').textContent='Back to Crow HQ ↗';cv.setAttribute('aria-label','Suria KLCC '+floor().name+' pixel floor plan. Use Browse shops to find and visit every listed shop, or click a numbered shop on the map.');renderKey='';render();return true;}
// Geometry is adapted from the mall's official wayfinding data. Only tenant outlines are rendered.
function mapPoint(point){return {x:850+(point[0]-512)*1.05,y:500+(point[1]-512)*1.05};}
function polygon(points,fill,stroke='#9aaa8c'){if(!points?.length)return;ctx.beginPath();points.forEach((p,i)=>{const q=mapPoint(p);i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y);});ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke();}
function drawMall(){const f=floor(),shops=currentShops();R(0,0,1400,1000,'#dce3cf');for(let y=0;y<1000;y+=32)for(let x=0;x<1400;x+=32)R(x,y,1,1,'#b5c2a466');R(34,72,280,302,'#f6f1db');R(34,72,280,7,f.color);T('SURIA',57,122,'#647551',36);T('K L C C',58,148,'#a18e64',19);T('THE MALL AT CROW HQ',58,180,'#8b977a',10);T(f.label,55,263,f.color,72);T(f.name.toUpperCase(),58,292,'#697951',16);T(f.theme,58,321,'#8d987d',11);T(shops.length+' SHOPS & DESTINATIONS',58,349,'#8b977a',10);T('CLICK A SHOP TO VISIT',58,419,'#667a51',12);T('Or use Browse shops above.',58,445,'#859575',11);T('Click a corridor to take a walk.',58,490,'#859575',10);T('Lift buttons connect all six floors.',58,468,'#859575',10);T('Real units. A pixel little world.',58,520,'#859575',10);
 const nodes=MALL_PATHS[f.id]||[],byId=new Map(nodes.map(n=>[n.id,n]));
 ctx.lineJoin='round';ctx.lineCap='round';for(const [color,width] of [['#bac6a5',39],['#f0e9cc',34]]){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();for(const n of nodes)for(const id of n.neighbors){const a=mapPoint(n.point),b=mapPoint(byId.get(id).point);ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);}ctx.stroke();}ctx.lineCap='butt';
 const geometry=MALL_GEOMETRY[f.id]||[];for(const g of geometry){const tenant=shops.find(s=>g.shopIds.includes(s.id));const color=tenant?(selected===tenant.id?'#d7ed9b':colors[hash(tenant.category||tenant.name)%colors.length]):'#eee8cd';for(const poly of g.polygons)polygon(poly,color,'#abb595');}

 for(let i=0;i<shops.length;i++){const s=shops[i];const q=mapPoint(s.point||[0,0]);R(q.x-9,q.y-9,18,17,selected===s.id?'#7b9451':'#f9f4df');T(String(i+1).padStart(2,'0'),q.x-6,q.y+3,'#62714f',9);const g=geometry.find(g=>g.shopIds.includes(s.id));const poly=g?.polygons?.[0];if(poly){const width=Math.max(...poly.map(p=>p[0]))-Math.min(...poly.map(p=>p[0]));if(width>64){const label=s.name.slice(0,Math.min(20,Math.floor(width/5)));ctx.font='9px monospace';const tw=ctx.measureText(label).width;R(q.x-tw/2-3,q.y+12,tw+6,14,'#faf5e0ee');T(label,q.x-tw/2,q.y+22,'#62714f',9);}}}
 // Atrium glow, lift & orientation remain in the actual plan's central open space.
 T('ATRIUM',815,485,'#a39771',12);T('↓ PARK / ESPLANADE',762,952,'#80926d',12);R(367,943,3,20,'#a0b18c');T('N ↑',376,957,'#81926d',11);
 const active=shopById(selected);if(active&&active.floor===f.id){R(43,535,265,105,'#faf6e2');T(active.name.slice(0,27),56,563,'#60764d',14);T(active.unit.slice(0,36),56,589,'#93956d',10);T('SELECTED · CLICK TO ENTER',56,618,'#83985c',10);}
 T('OFFICIAL TENANT OUTLINES / SIMPLIFIED PIXEL WAYFINDING',400,982,'#9aa484',9);
}
function drawStore(){const s=shop(),f=floor(),sports=itemsFor(s).length>0,accent=sports?(s.name.toLowerCase().includes('nike')?'#596c76':'#668478'):f.color;R(0,0,1400,1000,'#dae2cd');R(330,95,1010,760,'#a6b394');R(340,105,990,740,'#eee7cc');for(let y=115;y<835;y+=36)R(348,y,975,1,'#c8c6ab66');for(let x=348;x<1325;x+=48)R(x,115,1,720,'#c8c6ab66');R(340,105,990,166,'#e6dfc5');R(340,263,990,12,accent);R(582,135,513,61,accent);T(s.name.toUpperCase().slice(0,32),610,174,'#faf3d5',23);T(f.name.toUpperCase()+' / '+s.unit,610,223,'#8b9277',12);T('SURIA KLCC',53,116,'#7f8e6b',18);T('A LITTLE',53,166,'#a38f61',14);T('WINDOW SHOPPING',53,191,'#65784f',17);T('Make yourself at home.',53,228,'#8b987c',11);T(sports?'Collect a look above the map.':'Explore the shop with a friend.',53,254,'#8b987c',10);
 for(let i=0;i<4;i++){const x=390+i*232;R(x,320,180,13,accent);R(x+7,333,166,128,'#c4ceb3');R(x+12,340,156,102,'#f2ebd1');if(sports){for(let j=0;j<3;j++){R(x+25+j*46,366,26,43,colors[(i+j)%colors.length]);R(x+20+j*46,367,37,12,colors[(i+j)%colors.length]);}R(x+12,414,156,5,'#a6b18e');}else{for(let j=0;j<4;j++){R(x+20+j*34,368-(j%2)*12,23,45+(j%2)*12,colors[(i+j)%6]);R(x+24+j*34,359-(j%2)*12,15,9,'#f2e0b6');}}R(x+7,459,166,9,'#a2ad8b');}
 R(720,540,280,117,'#b79d73');R(711,529,298,22,'#e0c89b');T(sports?'THE PIXEL COLLECTION':'NEW DISCOVERIES',752,581,'#f5ebcc',15);const its=itemsFor(s);its.slice(0,3).forEach((item,i)=>drawItem(ctx,item,760+i*86,525,1.5));R(1120,560,131,85,accent);R(1113,548,145,19,'#d1ba8e');R(1152,502,57,45,'#6d8170');R(1158,508,45,28,'#bbceb0');T('WELCOME',1132,597,'#f6eccf',12);R(380,748,930,11,'#bcc8a7');R(727,846,136,12,'#c4cdb1');T('BACK TO THE MALL CORRIDOR ↑',672,895,'#7c8f69',12);T('PIXEL VISIT / '+s.name.toUpperCase().slice(0,40),395,810,'#9aa282',11);
}
function draw(){shop()?drawStore():drawMall();}
function nearestNode(point){let best=null,d=Infinity;for(const n of MALL_PATHS[floor().id]||[]){const q=mapPoint(n.point),v=Math.hypot(q.x-point[0],q.y-point[1]);if(v<d){d=v;best=n;}}return best;}
function route(from,to){if(shop())return[to];const nodes=MALL_PATHS[floor().id]||[],byId=new Map(nodes.map(n=>[n.id,n])),start=nearestNode(from),end=nearestNode(to);if(!start||!end)return[to];const queue=[start.id],previous=new Map([[start.id,null]]);for(let i=0;i<queue.length;i++){const id=queue[i];if(id===end.id)break;for(const next of byId.get(id).neighbors)if(!previous.has(next)){previous.set(next,id);queue.push(next);}}if(!previous.has(end.id))return[to];const ids=[];for(let id=end.id;id!==null;id=previous.get(id))ids.push(id);return ids.reverse().map(id=>{const p=mapPoint(byId.get(id).point);return[p.x,p.y];}).concat([to]);}
function position(p,index){if(p.shopId)return{x:800+(index%5)*65,y:730+Math.floor(index/5)*42};const nodes=MALL_PATHS[floorForSpot(p.spot)?.id]||[],node=nodes.find(n=>n.id===p.mallNode)||nodes.find(n=>Math.hypot(n.point[0]-500,n.point[1]-560)<40)||nodes[0];const pos=mapPoint(node?.point||[512,512]);return{x:pos.x+(index%3)*12,y:pos.y+Math.floor(index/3)*13};}

function handleClick(x,y){if(shop()){if(y>845&&y<920&&x>650&&x<950)window.CrowCommunity.shop(null);return true;}let nearest=null,d=42;for(const s of currentShops()){const p=mapPoint(s.point||[0,0]),distance=Math.hypot(x-p.x,y-p.y);if(distance<d){d=distance;nearest=s;}}if(nearest){selected=nearest.id;enter(nearest.id);}else{const node=nearestNode([x,y]);if(node)window.CrowCommunity.mallWalk(node.id);}return true;}
window.CrowMall={currentShop:shop,render,route,draw,openScene,position,handleClick,openDirectory};
$m('#mall-enter').onclick=()=>{if(!me())return toast('Create your character first.');window.CrowCommunity.go('mall-g');};$m('#wardrobe-open').onclick=openWardrobe;
